<script setup>
import { ref } from 'vue';import { useRoute, useRouter } from 'vue-router';import { LogIn, ShieldCheck, Eye, EyeOff, ArrowLeft } from '@lucide/vue'
import AppLogo from '../../components/AppLogo.vue';import { authStore } from '../../stores/auth';import { uiStore } from '../../stores/ui'
